    if not text:
        return []

    escapes = {"\\": "\\", "|": "|", '"': '"', "n": "\n"}
    records: list[list[str]] = []
    fields: list[str] = []
    length = len(text)
    index = 0

    while True:
        decoded: list[str] = []
