def revision_log(events: list[tuple]) -> list[tuple]:
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    validated = []
    for position, event in enumerate(events):
        if not isinstance(event, tuple) or len(event) != 5:
            raise ValueError("each event must be a five-element tuple")

        event_id, revision, operation, key, value = event

        if not isinstance(event_id, str):
            raise ValueError("event id must be a string")
        if type(revision) is not int or revision < 0:
            raise ValueError("revision must be a nonnegative exact int")
        if not isinstance(operation, str) or operation not in ("set", "delete", "undo"):
            raise ValueError("operation must be 'set', 'delete', or 'undo'")
        if not isinstance(key, str):
            raise ValueError("event key must be a string")

        validated.append((position, event_id, revision, operation, key, value))

    winners = {}
    for event in validated:
        position, event_id, revision, operation, key, value = event
        previous = winners.get(event_id)
        if previous is None or revision >= previous[2]:
            winners[event_id] = event

    retained = sorted(winners.values(), key=lambda event: event[0])

    disabled = set()
    for position, event_id, revision, operation, key, value in retained:
        if operation == "undo":
            target = winners.get(key)
            if target is None or target[3] == "undo" or target[0] >= position:
                raise ValueError(
                    "undo must target a strictly earlier retained non-undo event"
                )
            disabled.add(key)

    result = {}
    for position, event_id, revision, operation, key, value in retained:
        if operation == "undo" or event_id in disabled:
            continue
        if operation == "set":
            result[key] = value
        else:
            result.pop(key, None)

    return deepcopy(list(result.items()))

