def patch_spans(text: str, edits: list[tuple[int, int, str]]) -> str:
    """Apply edits whose coordinates refer to the original text."""
    validated = []
    text_length = len(text)

    for edit in edits:
        try:
            start, end, replacement = edit
        except (TypeError, ValueError):
            raise ValueError("Each edit must contain exactly three items.") from None

        if type(start) is not int or type(end) is not int:
            raise ValueError("Edit endpoints must be exact integers.")
        if not 0 <= start <= end <= text_length:
            raise ValueError("Edit endpoints are outside the valid range.")
        if not isinstance(replacement, str):
            raise ValueError("Edit replacements must be strings.")

        validated.append((start, end, replacement))

    # Stable sorting preserves insertion order at each coordinate and places
    # insertions before any replacement starting at that coordinate.
    validated.sort(key=lambda edit: (edit[0], edit[1]))

    previous_end = 0
    for start, end, _ in validated:
        if start < previous_end:
            raise ValueError(
                "Replacements must not overlap, and insertions must not "
                "lie strictly inside replacements."
            )
        previous_end = end

    parts = []
    cursor = 0
    for start, end, replacement in validated:
        parts.append(text[cursor:start])
        parts.append(replacement)
        cursor = end

    parts.append(text[cursor:])
    return "".join(parts)

