    cells = [
        (r, c)
        for r, row in enumerate(rows)
        for c in range(len(row))
    ]
    if not cells:
        return []

    remaining = set(cells)
    directions = ((0, 1), (1, 0), (0, -1), (-1, 0))
    direction = 0
    restart_index = 0
    r, c = cells[0]
