from collections.abc import Iterator


def _folded_units(text: str, ignore_marks: bool) -> Iterator[tuple[int, str]]:
    start = 0
    for end in range(1, len(text) + 1):
        if end < len(text) and unicodedata.combining(text[end]) != 0:
            continue

