def transaction_frames(
    initial: dict[str, int], commands: list[tuple]
) -> tuple[dict, list[bool]]:
    if not isinstance(initial, dict) or not isinstance(commands, list):
        raise ValueError("Expected a dictionary and a list of commands")

    for account, balance in initial.items():
        if not isinstance(account, str):
            raise ValueError("Account names must be strings")
        if type(balance) is not int or balance < 0:
            raise ValueError("Balances must be nonnegative exact integers")

    balances = initial.copy()
    frames: list[tuple[dict[str, int], bool]] = []
    results: list[bool] = []

    for command in commands:
        if not isinstance(command, tuple) or not command:
            raise ValueError("Commands must be nonempty tuples")

        operation = command[0]
        if not isinstance(operation, str):
            raise ValueError("Command names must be strings")

        if operation == "move":
            if len(command) != 4:
                raise ValueError("Move requires source, destination, and amount")

            _, src, dst, amount = command
            if not isinstance(src, str) or not isinstance(dst, str):
                raise ValueError("Account names must be strings")
            if src not in balances or dst not in balances:
                raise ValueError("Both accounts must exist")
            if type(amount) is not int or amount < 0:
                raise ValueError("Amounts must be nonnegative exact integers")

            if frames and frames[-1][1]:
                continue
            if src == dst:
                continue

            current = frames[-1][0] if frames else balances
            if current[src] < amount:
                if frames:
                    frames[-1] = (current, True)
                continue

            current[src] -= amount
            current[dst] += amount

        elif operation == "begin":
            if len(command) != 1:
                raise ValueError("Begin takes no arguments")
            if frames and frames[-1][1]:
                raise ValueError("Cannot begin inside a failed frame")

            current = frames[-1][0] if frames else balances
            frames.append((current.copy(), False))

        elif operation == "commit":
            if len(command) != 1:
                raise ValueError("Commit takes no arguments")
            if not frames:
                raise ValueError("Commit requires an open frame")

            current, failed = frames.pop()
            results.append(not failed)
            if not failed:
                if frames:
                    frames[-1] = (current, frames[-1][1])
                else:
                    balances = current

        elif operation == "rollback":
            if len(command) != 1:
                raise ValueError("Rollback takes no arguments")
            if not frames:
                raise ValueError("Rollback requires an open frame")
            frames.pop()

        else:
            raise ValueError("Unknown command")

    if frames:
        raise ValueError("Unbalanced frames")

    return balances, results

