    total: int, weights: list[int], caps: list[int]
) -> list[int]:
    allocations = [0] * len(weights)
    active = [
        i for i in range(len(weights))
        if weights[i] > 0 and caps[i] > 0
    ]
    remaining = total

    while remaining > 0:
        weight_sum = sum(weights[i] for i in active)
        saturated = [
